"""Verify the nested columns parquet data file which is generated by the pure
VB.NET parquet writer (the ``Frames.MakeNested`` fixture).

usage:
    python verify_vb_nested.py <parquet-file>

Prints one ``PASS``/``FAIL`` line for each check plus a final ``SUMMARY`` line.
"""

import sys

import pyarrow as pa
import pyarrow.parquet as pq

passed = 0
failed = 0


def report(ok, name, expected=None, actual=None):
    global passed, failed

    if ok:
        passed += 1
        sys.stdout.write("PASS %s\n" % name)
    else:
        failed += 1
        sys.stdout.write("FAIL %s expected=%r actual=%r\n" % (name, expected, actual))


def pair_list(value):
    if value is None:
        return None

    return [[item["key"], item["value"]] for item in value]


def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: python verify_vb_nested.py <parquet-file>\n")
        return 2

    table = pq.read_table(sys.argv[1])
    schema = table.schema

    report(table.num_rows == 5, "rows", 5, table.num_rows)
    # 4 个数据列 + 1 个 __index__ 行名列
    report(len(schema.names) == 5, "columns", 5, len(schema.names))

    for name in ("values", "attrs", "points", "record", "__index__"):
        report(name in schema.names, "column %s exists" % name)

    if "values" not in schema.names:
        sys.stdout.write("SUMMARY pass=%d fail=%d\n" % (passed, failed))
        return 1

    report(pa.types.is_list(schema.field("values").type), "values is LIST", "list", str(schema.field("values").type))
    report(pa.types.is_map(schema.field("attrs").type), "attrs is MAP", "map", str(schema.field("attrs").type))
    report(pa.types.is_list(schema.field("points").type), "points is LIST", "list", str(schema.field("points").type))
    report(pa.types.is_struct(schema.field("record").type), "record is STRUCT", "struct", str(schema.field("record").type))

    rows = table.to_pylist()

    report(rows[0]["values"] == [1.0, 2.0, 3.0], "values[0]", [1.0, 2.0, 3.0], rows[0]["values"])
    report(rows[1]["values"] == [4.5], "values[1]", [4.5], rows[1]["values"])
    report(rows[2]["values"] == [], "values[2] empty list", [], rows[2]["values"])
    report(rows[3]["values"] is None, "values[3] null", None, rows[3]["values"])
    report(rows[4]["values"] == [6.0, 7.0], "values[4]", [6.0, 7.0], rows[4]["values"])

    report(pair_list(rows[0]["attrs"]) == [["a", 1], ["b", 2]], "attrs[0]",
           [["a", 1], ["b", 2]], pair_list(rows[0]["attrs"]))
    report(pair_list(rows[1]["attrs"]) == [], "attrs[1] empty map", [], pair_list(rows[1]["attrs"]))
    report(rows[3]["attrs"] is None, "attrs[3] null", None, rows[3]["attrs"])
    report(pair_list(rows[4]["attrs"]) == [["d", 4], ["e", 5]], "attrs[4]",
           [["d", 4], ["e", 5]], pair_list(rows[4]["attrs"]))

    report(rows[0]["points"] == [{"x": 1, "y": 1.5}, {"x": 2, "y": 2.5}], "points[0]",
           [{"x": 1, "y": 1.5}, {"x": 2, "y": 2.5}], rows[0]["points"])
    report(rows[1]["points"] == [], "points[1] empty list", [], rows[1]["points"])
    report(rows[3]["points"] is None, "points[3] null", None, rows[3]["points"])

    report(rows[0]["record"] == {"a": 1, "l": [1, 2]}, "record[0]",
           {"a": 1, "l": [1, 2]}, rows[0]["record"])
    report(rows[1]["record"] == {"a": 2, "l": []}, "record[1]",
           {"a": 2, "l": []}, rows[1]["record"])
    report(rows[3]["record"] is None, "record[3] null", None, rows[3]["record"])
    report(rows[4]["record"] == {"a": 5, "l": [5, 6, 7]}, "record[4]",
           {"a": 5, "l": [5, 6, 7]}, rows[4]["record"])

    sys.stdout.write("SUMMARY pass=%d fail=%d\n" % (passed, failed))

    return 0 if failed == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
